These two functions complete the ScaleKit integration.
The connector routing in ^executeTool^ uses the tool name prefix to select the right connection explicitly, which is the correct pattern when a user has multiple accounts for the same provider:
export async function listScopedTools(
userId: string,
connectionNames: string[],
): Promise {
const { tools } = await scalekit.tools.listScopedTools(userId, {
filter: { connectionNames },
pageSize: 100,
});
return tools.map(t => ({
name: t.tool.definition.name as string,
description: t.tool.definition.description as string,
input_schema: t.tool.definition.input_schema as Anthropic.Tool['input_schema'],
}));
}
